//! Bounces through the console (automated).
//!
//! `examples/projects/pdc-clicks.atomik` is generated by [`pdc_clicks_doc`] through model
//! commands (so it is valid and canonical). After a deliberate change, regenerate it with:
//!
//! ```text
//! ATOMIK_UPDATE_GOLDEN=1 cargo test -p atomik-render --test console example
//! ```
//!
//! **The click project.** Two identical click synths (a short note on every beat) each play
//! through their own console channel: "Click A" panned hard left, "Click B" hard right. Click
//! B's insert loop holds a *device with 2400 samples of latency*, built from two plain channel
//! strips (there is no latency effect in the device set yet): `latency-delay` really delays
//! by 2400 samples without reporting it (`latency.adjust = +2400`), `latency-report` reports
//! 2400 samples without delaying (`latency.adjust = −2400`). Together they delay by 2400 and
//! report 2400, like a look-ahead plug-in. With compensation on, the engine delays Click A
//! by 2400 so both clicks reach the master together; with it off, Click B lands 2400 samples
//! (50 ms at 48 kHz) after Click A.

use atomik_core::PPQ;
use atomik_model::{
    Cable, Clip, ClipContent, ClipId, Command, Document, Note, RackDoc, SocketRef, SongCommand,
    empty_doc, load_project, save_project,
};
use atomik_model::{DeviceKey, INTERFACE_KEY};
use atomik_render::default_registry;
use atomik_render::project::{ProjectOptions, render_doc, render_project_json};
use std::num::NonZeroUsize;
use std::path::{Path, PathBuf};

/// The latency of Click B's insert in the example, samples.
const LATENCY: usize = 2400;
/// One beat at 120 BPM, 48 kHz.
const BEAT: usize = 24_000;
/// Fader position for +3 dB (makes up the −3 dB centre pan of each insert strip).
const PLUS_3_DB: f32 = 0.841_9;

fn example_path(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../examples/projects")
        .join(name)
}

fn key(k: &str) -> DeviceKey {
    DeviceKey(k.to_string())
}

fn sref(d: &str, s: &str) -> SocketRef {
    SocketRef {
        device: key(d),
        socket: s.to_string(),
    }
}

/// Builds the click project (module docs).
fn pdc_clicks_doc() -> RackDoc {
    let registry = default_registry();
    let mut doc = Document::new(empty_doc());
    let mut apply = |c: Command| {
        doc.apply(c.clone(), &registry)
            .unwrap_or_else(|e| panic!("{c:?}: {e}"));
    };
    let set = |k: &str, p: &str, v: f32| Command::SetParam {
        key: key(k),
        param: p.into(),
        value: v,
        merge: None,
    };
    for (k, name) in [("click-a", "Click A"), ("click-b", "Click B")] {
        apply(Command::AddDevice {
            index: usize::MAX,
            type_id: "atomik.poly-synth".into(),
            key: Some(key(k)),
        });
        apply(Command::Rename {
            key: key(k),
            name: name.into(),
        });
        for (p, v) in [
            ("osc1.wave", 1.0),
            ("osc.mix", 0.0),
            ("filter.cutoff", 20_000.0),
            ("filter.env_amount", 0.0),
            ("filter.key_track", 0.0),
            ("filter.resonance", 0.0),
            ("env.amp.attack", 0.5),
            ("env.amp.decay", 25.0),
            ("env.amp.sustain", 0.0),
            ("env.amp.release", 0.5),
            ("voices", 1.0),
        ] {
            apply(set(k, p, v));
        }
    }
    let doc_now = |d: &Document, source: &str| {
        d.doc()
            .console
            .channel_of(&key(source))
            .unwrap()
            .channel
            .0
            .clone()
    };
    let (ch_a, ch_b) = (doc_now(&doc, "click-a"), doc_now(&doc, "click-b"));
    let mut apply = |c: Command| {
        doc.apply(c.clone(), &registry)
            .unwrap_or_else(|e| panic!("{c:?}: {e}"));
    };
    for (ch, name, pan) in [(&ch_a, "Click A", -1.0), (&ch_b, "Click B", 1.0)] {
        apply(Command::Rename {
            key: key(ch),
            name: name.into(),
        });
        apply(set(ch, "pan", pan));
    }
    // The 2400-sample "latency device" in Click B's insert loop.
    for (k, name, adjust) in [
        ("latency-delay", "Latency 2400 (delay)", LATENCY as f32),
        ("latency-report", "Latency 2400 (report)", -(LATENCY as f32)),
    ] {
        apply(Command::AddDevice {
            index: usize::MAX,
            type_id: "atomik.channel".into(),
            key: Some(key(k)),
        });
        apply(Command::Rename {
            key: key(k),
            name: name.into(),
        });
        apply(set(k, "latency.adjust", adjust));
        apply(set(k, "fader", PLUS_3_DB));
    }
    for side in ["l", "r"] {
        for (from, to) in [
            (
                sref(&ch_b, &format!("insert_send_{side}")),
                sref("latency-delay", &format!("in_{side}")),
            ),
            (
                sref("latency-delay", &format!("out_{side}")),
                sref("latency-report", &format!("in_{side}")),
            ),
            (
                sref("latency-report", &format!("out_{side}")),
                sref(&ch_b, &format!("insert_return_{side}")),
            ),
        ] {
            apply(Command::Connect(Cable { from, to }));
        }
    }
    let bars = 4;
    let length = bars * 4 * PPQ;
    for k in ["click-a", "click-b"] {
        apply(Command::Song(SongCommand::AddTrack { device: key(k) }));
        let notes = (0..bars * 4)
            .map(|b| Note::new(b * PPQ, PPQ / 8, 84, 1.0))
            .collect();
        apply(Command::Song(SongCommand::AddClip {
            device: key(k),
            lane: 0,
            clip: Clip {
                id: ClipId(0),
                start: 0,
                length,
                offset: 0,
                loop_length: None,
                muted: false,
                scale: None,
                controllers: Vec::new(),
                grid: None,
                content: ClipContent::Notes(notes),
            },
        }));
    }
    apply(Command::Song(SongCommand::SetSongEnd(length)));
    apply(Command::Song(SongCommand::SetLoop {
        range: (0, length),
        enabled: true,
    }));
    let doc = doc.doc().clone();
    assert!(doc.console.compensation);
    assert!(
        doc.cables
            .iter()
            .any(|c| c.to.device.as_str() == INTERFACE_KEY),
        "the master feeds the interface"
    );
    doc
}

fn options(block: usize, workers: u16) -> ProjectOptions {
    ProjectOptions {
        host_block: NonZeroUsize::new(block).unwrap(),
        workers,
        loop_count: None,
    }
}

fn bits(channels: &[Vec<f32>]) -> Vec<u32> {
    channels.iter().flatten().map(|x| x.to_bits()).collect()
}

fn clicks() -> RackDoc {
    let text = std::fs::read_to_string(example_path("pdc-clicks.atomik")).expect("example");
    load_project(&text, &default_registry()).expect("valid example")
}

/// First sample at or after `from` that is not exactly zero.
fn onset(x: &[f32], from: usize) -> usize {
    from + x[from..].iter().position(|v| *v != 0.0).expect("a click")
}

#[test]
fn the_pdc_clicks_example_is_generated_and_canonical() {
    let doc = pdc_clicks_doc();
    let text = save_project(&doc);
    let path = example_path("pdc-clicks.atomik");
    if std::env::var_os("ATOMIK_UPDATE_GOLDEN").is_some_and(|v| v == "1") {
        std::fs::write(&path, &text).unwrap();
    }
    let on_disk = std::fs::read_to_string(&path).expect("example file");
    assert!(
        on_disk == text,
        "pdc-clicks.atomik is stale (see module docs)"
    );
    assert_eq!(load_project(&on_disk, &default_registry()).unwrap(), doc);
}

/// Clicks align at the master with compensation on, and are offset
/// by exactly the insert latency with it off.
#[test]
fn e4_2_clicks_align_with_compensation_and_are_offset_without() {
    let registry = default_registry();
    let mut doc = clicks();
    let on = render_doc(&doc, &registry, &options(512, 0))
        .unwrap()
        .channels;
    doc.console.compensation = false;
    let off = render_doc(&doc, &registry, &options(512, 0))
        .unwrap()
        .channels;
    // Beat 0 is checked by `e4_2_beat_0_aligns_too`.
    for beat in 1..8 {
        let at = beat * BEAT;
        // Click A is alone on the left, Click B alone on the right.
        let (a_on, b_on) = (onset(&on[0], at), onset(&on[1], at));
        let (a_off, b_off) = (onset(&off[0], at), onset(&off[1], at));
        assert_eq!(a_on, b_on, "beat {beat}: aligned with compensation");
        assert_eq!(b_off - a_off, LATENCY, "beat {beat}: offset without");
        assert_eq!(a_on - a_off, LATENCY, "compensation delays Click A");
        assert_eq!(b_on, b_off, "Click B is never delayed by compensation");
        assert!(a_off - at < 64, "the click starts at its beat");
    }
}

/// At beat 0, the first batch after `prepare`: clicks align sample-exactly from the very
/// first beat (devices snap their params, including the insert crossfade, on the first batch).
#[test]
fn e4_2_beat_0_aligns_too() {
    let registry = default_registry();
    let mut doc = clicks();
    let on = render_doc(&doc, &registry, &options(512, 0))
        .unwrap()
        .channels;
    doc.console.compensation = false;
    let off = render_doc(&doc, &registry, &options(512, 0))
        .unwrap()
        .channels;
    // Nothing reaches the master before the compensated clicks.
    assert!(on.iter().all(|c| c[..LATENCY].iter().all(|v| *v == 0.0)));
    let (a_on, b_on) = (onset(&on[0], 0), onset(&on[1], 0));
    let (a_off, b_off) = (onset(&off[0], 0), onset(&off[1], 0));
    assert_eq!(a_on, b_on);
    assert_eq!(b_off - a_off, LATENCY);
    let n = on[0].len();
    // Equal up to float rounding (1 ULP): constant-power hard pan leaks sin(0) ~ 6e-17 of each
    // click into the other side, so the master sums the two contributions in a different order
    // when one of them is delayed. Measured max difference: 1.5e-8 (about -156 dB).
    let max_diff = on[0][LATENCY..]
        .iter()
        .zip(&off[0][..n - LATENCY])
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max);
    assert!(
        max_diff < 1e-6,
        "compensated vs shifted differ by {max_diff}"
    );
    assert!(bits(&[on[1].clone()]) == bits(&[off[1].clone()]));
}

/// HI-2: a bounce with active PDC delay lines is bit-identical across host blocks and
/// worker counts, compensation on and off.
#[test]
fn ac_x4_console_bounces_with_pdc_are_bit_identical_across_blocks_and_workers() {
    let registry = default_registry();
    for compensation in [true, false] {
        let mut doc = clicks();
        doc.console.compensation = compensation;
        let reference = bits(
            &render_doc(&doc, &registry, &options(64, 0))
                .unwrap()
                .channels,
        );
        for block in [1, 64, 4096] {
            for workers in [0, 4] {
                let got = render_doc(&doc, &registry, &options(block, workers)).unwrap();
                assert!(
                    bits(&got.channels) == reference,
                    "compensation {compensation}, block {block}, workers {workers} differ"
                );
            }
        }
    }
}

/// The demo is a v2 project through the console (two channels, the echo on return 1).
#[test]
fn the_demo_bounces_through_its_console() {
    let text = std::fs::read_to_string(example_path("demo.atomik")).unwrap();
    let registry = default_registry();
    let doc = load_project(&text, &registry).unwrap();
    assert_eq!(doc.console.channels.len(), 2);
    assert!(doc.console.master.is_some());
    assert_eq!(doc.console.returns[0], Some(key("echo")));
    let r = render_project_json(&text, &registry, &options(512, 0)).unwrap();
    assert!(r.channels.iter().all(|c| c.iter().any(|v| *v != 0.0)));
}

/// In the bounce: soloing one channel sounds exactly like muting the others (solo
/// silence is applied like the app does, through `internal.solo_silence`).
#[test]
fn soloing_a_channel_bounces_like_muting_the_others() {
    let text = std::fs::read_to_string(example_path("demo.atomik")).unwrap();
    let registry = default_registry();
    let doc = load_project(&text, &registry).unwrap();
    let (bass, lead) = (
        doc.console.channels[0].channel.clone(),
        doc.console.channels[1].channel.clone(),
    );
    let with = |k: &DeviceKey, p: &str| {
        let mut d = Document::new(doc.clone());
        d.apply(
            Command::SetParam {
                key: k.clone(),
                param: p.into(),
                value: 1.0,
                merge: None,
            },
            &registry,
        )
        .unwrap();
        d.doc().clone()
    };
    let solo = render_doc(&with(&bass, "solo"), &registry, &options(512, 0)).unwrap();
    let mute = render_doc(&with(&lead, "mute"), &registry, &options(512, 0)).unwrap();
    let plain = render_doc(&doc, &registry, &options(512, 0)).unwrap();
    assert!(bits(&solo.channels) == bits(&mute.channels));
    assert!(bits(&solo.channels) != bits(&plain.channels));
}
